import React, { Component } from 'react';
import axios from 'axios';
import MyContext from '../contexts/MyContext';
import '../css/ReportComponent.css';

const formatDateInput = (date) => {
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${date.getFullYear()}-${month}-${day}`;
};

const initialDateRange = () => {
  const today = new Date();
  return {
    fromDate: formatDateInput(new Date(today.getFullYear(), today.getMonth(), 1)),
    toDate: formatDateInput(today)
  };
};

const shortDateLabel = (value) => {
  const [, month, day] = String(value || '').split('-');
  return month && day ? `${day}/${month}` : value;
};

class ReportComponent extends Component {
  static contextType = MyContext;

  constructor(props) {
    super(props);
    const { fromDate, toDate } = initialDateRange();
    this.state = {
      fromDate,
      toDate,
      stats: { revenue: 0, expenses: 0, profit: 0, orders: 0, customers: 0, products: 0 },
      chartData: [],
      tableRequests: [],
      topProducts: [],
      loading: false,
      showToast: false,
      toastMsg: '',
      toastType: 'success'
    };
  }

  componentDidMount() {
    this.apiGetReports();
  }

  componentWillUnmount() {
    clearTimeout(this.toastTimer);
  }

  apiGetReports = () => {
    const { fromDate, toDate } = this.state;
    const config = { 
      headers: { 'x-access-token': this.context.token },
      params: { fromDate, toDate }
    };
    this.setState({ loading: true });
    return axios.get('/api/admin/reports', config).then((res) => {
      if (res.data) {
        this.setState({
          stats: {
            revenue: res.data.revenue || 0,
            expenses: res.data.expenses || 0,
            profit: res.data.profit || 0,
            orders: res.data.orders || 0,
            customers: res.data.customers || 0,
            products: res.data.products || 0
          },
          chartData: res.data.chartData || [],
          tableRequests: res.data.tableRequests || [],
          topProducts: res.data.topProducts || []
        });
      }
      return true;
    }).catch((error) => {
      console.error('Không thể tải báo cáo:', error);
      return false;
    }).finally(() => this.setState({ loading: false }));
  };

  showToast = (message, type = 'success') => {
    clearTimeout(this.toastTimer);
    this.setState({ showToast: true, toastMsg: message, toastType: type });
    this.toastTimer = setTimeout(() => this.setState({ showToast: false }), 3000);
  };

  btnFilterClick = async (e) => {
    e.preventDefault();
    const { fromDate, toDate, loading } = this.state;
    if (loading) return;
    if (!fromDate || !toDate || fromDate > toDate) {
      this.showToast('Ngày bắt đầu phải trước hoặc bằng ngày kết thúc.', 'error');
      return;
    }
    const loaded = await this.apiGetReports();
    this.showToast(
      loaded ? 'Đã lọc báo cáo theo khoảng ngày.' : 'Không thể tải dữ liệu báo cáo.',
      loaded ? 'success' : 'error'
    );
  };

  render() {
    const {
      fromDate, toDate, stats, chartData, tableRequests, topProducts,
      loading, showToast, toastMsg, toastType
    } = this.state;
    const safeChartData = Array.isArray(chartData) ? chartData : [];
    const chartWidth = Math.max(600, safeChartData.length * 48);
    const chartPadding = 28;
    const maxRevenue = safeChartData.reduce((max, item) => Math.max(max, Number(item.revenue) || 0), 1);
    const chartX = (index) => safeChartData.length === 1
      ? chartWidth / 2
      : chartPadding + (index / (safeChartData.length - 1)) * (chartWidth - chartPadding * 2);
    const chartY = (item) => 154 - ((Number(item.revenue) || 0) / maxRevenue) * 126;
    const labelInterval = Math.max(1, Math.ceil(safeChartData.length / 12));
    const points = safeChartData.map((item, index) => {
      return `${chartX(index)},${chartY(item)}`;
    }).join(' ');

    return (
      <div className="report-container">
        <h3 className="report-title">QUẢN LÝ CỬA HÀNG</h3>

        <form className="filter-bar" onSubmit={this.btnFilterClick}>
          <label htmlFor="report-from-date"><b>Từ ngày:</b></label>
          <input
            id="report-from-date"
            type="date"
            className="filter-input"
            value={fromDate}
            max={toDate}
            onChange={(e) => this.setState({ fromDate: e.target.value })}
            required
          />
          <label htmlFor="report-to-date"><b>Đến ngày:</b></label>
          <input
            id="report-to-date"
            type="date"
            className="filter-input"
            value={toDate}
            min={fromDate}
            onChange={(e) => this.setState({ toDate: e.target.value })}
            required
          />
          <button className="filter-btn" type="submit" disabled={loading}>
            {loading ? 'Đang lọc...' : 'Lọc dữ liệu'}
          </button>
        </form>

        {/* Thống kê */}
        <div className="stats-grid">
          <div className="stat-card">
            <div className="stat-title">Doanh thu trong kỳ</div>
            <div className="stat-value" style={{ color: '#2E7D32' }}>
              {(stats.revenue || 0).toLocaleString('vi-VN')} đ
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Chi phí vốn trong kỳ</div>
            <div className="stat-value" style={{ color: '#C62828' }}>
              {(stats.expenses || 0).toLocaleString('vi-VN')} đ
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Lợi nhuận trong kỳ</div>
            <div className="stat-value" style={{ color: stats.profit < 0 ? '#C62828' : '#2E7D32' }}>
              {(stats.profit || 0).toLocaleString('vi-VN')} đ
            </div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Số đơn hàng</div>
            <div className="stat-value" style={{ color: '#1E88E5' }}>{stats.orders || 0} đơn</div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Số khách hàng</div>
            <div className="stat-value" style={{ color: '#C85A32' }}>{stats.customers || 0} khách</div>
          </div>
          <div className="stat-card">
            <div className="stat-title">Số sản phẩm</div>
            <div className="stat-value" style={{ color: '#6A1B9A' }}>{stats.products || 0} món</div>
          </div>
        </div>

        {/* Biểu đồ doanh thu theo ngày và đơn hàng cần duyệt */}
        <div className="content-row">
          <div className="chart-box">
            <div className="chart-heading">
              <h4>Biểu đồ doanh thu theo ngày</h4>
              <span>{fromDate} – {toDate}</span>
            </div>
            {loading && safeChartData.length === 0 ? (
              <div className="chart-empty">Đang tải dữ liệu...</div>
            ) : safeChartData.length === 0 ? (
              <div className="chart-empty">Không có dữ liệu trong khoảng ngày này.</div>
            ) : (
              <div className="chart-scroll-area">
                <svg
                  viewBox={`0 0 ${chartWidth} 205`}
                  style={{ width: `${chartWidth}px`, height: '205px' }}
                  role="img"
                  aria-label="Biểu đồ doanh thu theo ngày"
                >
                  <line x1="0" y1="154" x2={chartWidth} y2="154" stroke="#e8dfd8" strokeWidth="1" />
                  <polyline fill="none" stroke="#C85A32" strokeWidth="3" points={points} />
                  {safeChartData.map((item, index) => (
                    <g key={item._id}>
                      <title>{`${item._id}: doanh thu ${(item.revenue || 0).toLocaleString('vi-VN')}đ, chi phí ${(item.expenses || 0).toLocaleString('vi-VN')}đ, lợi nhuận ${(item.profit || 0).toLocaleString('vi-VN')}đ`}</title>
                      <circle cx={chartX(index)} cy={chartY(item)} r="4.5" fill="#4A2E2B" />
                      {(index % labelInterval === 0 || index === safeChartData.length - 1) && (
                        <text x={chartX(index)} y="185" fontSize="11" textAnchor="middle" fill="#666">
                          {shortDateLabel(item._id)}
                        </text>
                      )}
                    </g>
                  ))}
                </svg>
              </div>
            )}
          </div>

          <div className="notification-box">
            <h4 style={{ marginBottom: '15px', color: '#4A2E2B' }}>Đơn hàng đang cần duyệt</h4>
            <div style={{ fontSize: '13px', lineHeight: '1.6' }}>
              {(!tableRequests || tableRequests.length === 0) ? (
                <div style={{ color: '#888', fontStyle: 'italic' }}>Không có đơn hàng chờ duyệt.</div>
              ) : (
                tableRequests.map((req) => (
                  <div key={req._id} style={{ padding: '10px', backgroundColor: '#FFF8E1', borderRadius: '6px', marginBottom: '8px' }}>
                    <div><b>Bàn: {req.tableNo || 'N/A'}</b> - {req.customerName || 'Khách'}</div>
                    <div style={{ color: '#C85A32', fontWeight: 'bold' }}>{(req.total || 0).toLocaleString('vi-VN')} đ</div>
                    <div style={{ fontSize: '11px', color: '#666' }}>{new Date(req.cdate).toLocaleDateString('vi-VN')}</div>
                  </div>
                ))
              )}
            </div>
          </div>
        </div>

        {/* 4. Top sản phẩm bán chạy */}
        <div className="top-products-box">
          <h4 style={{ marginBottom: '15px' }}>Sản phẩm bán chạy</h4>
          <div className="top-products-grid">
            {(!topProducts || topProducts.length === 0) ? (
              <div style={{ color: '#888', fontStyle: 'italic' }}>Chưa có dữ liệu sản phẩm bán chạy.</div>
            ) : (
              topProducts.map((item, index) => (
                <div key={item._id || index} className="product-item">
                  {item.image ? (
                    <img src={item.image} alt={item.name} className="product-img" />
                  ) : (
                    <div className="product-placeholder">#{index + 1}</div>
                  )}
                  <div>
                    <div style={{ fontWeight: 'bold', fontSize: '14px' }}>{item.name}</div>
                    <div style={{ color: '#C85A32', fontSize: '13px', fontWeight: 'bold' }}>
                      {(item.price || 0).toLocaleString('vi-VN')} đ
                    </div>
                  </div>
                </div>
              ))
            )}
          </div>
        </div>

        {showToast && (
          <div className={`toast-popup ${toastType}`} role="status" aria-live="polite">
            <span className="toast-icon">{toastType === 'error' ? '!' : '✓'}</span>
            <span>{toastMsg}</span>
          </div>
        )}

      </div>
    );
  }
}

ReportComponent.contextType = MyContext;

export default ReportComponent;
